def minimalBases(classes):
    """Reduce a list of base classes to its ordered minimum equivalent"""
    if not classes:
        return []

    # Create a set of all classes and their bases
    all_classes = set(classes)
    for cls in classes:
        all_classes.update(cls.__bases__)

    # Create a dictionary to track the direct bases of each class
    base_dict = {cls: set() for cls in all_classes}
    for cls in all_classes:
        for base in cls.__bases__:
            base_dict[base].add(cls)

    # Function to perform a topological sort
    def topological_sort():
        in_degree = {cls: 0 for cls in all_classes}
        for cls in all_classes:
            for base in base_dict[cls]:
                in_degree[base] += 1

        queue = [cls for cls in all_classes if in_degree[cls] == 0]
        result = []

        while queue:
            cls = queue.pop(0)
            result.append(cls)
            for base in base_dict[cls]:
                in_degree[base] -= 1
                if in_degree[base] == 0:
                    queue.append(base)

        return result

    # Get the topological order of classes
    ordered_classes = topological_sort()

    # Filter out the minimal bases
    minimal_bases = []
    for cls in ordered_classes:
        if all(base not in minimal_bases for base in cls.__bases__):
            minimal_bases.append(cls)

    return minimal_bases

