    The input variable prior is also expected to be an InventoryValidator object
    and both self and prior inventories are assumed to have been checked for
    internal consistency.
    """
    if not isinstance(prior, InventoryValidator):
        raise TypeError("The prior must be an instance of InventoryValidator")

    if self.inventory.keys() != prior.inventory.keys():
        raise ValueError("The prior inventory must have the same keys as the current inventory")

    for key in self.inventory:
        current_item = self.inventory[key]
        prior_item = prior.inventory[key]

        if current_item.version <= prior_item.version:
            raise ValueError(f"The current version of {key} ({current_item.version}) "
                             f"must be greater than the prior version ({prior_item.version})")

def get_logical_path_map(inventory, version):
    """Get a map of logical paths in state to files on disk for version in inventory.

    Returns a dictionary: logical_path_in_state -> set(content_files)

    The set of content_files may includes references to duplicate files in
    later versions than the version being described.
    """
    logical_path_map = {}

    for item in inventory:
        if item['version'] == version:
            for logical_path, content_files in item['files'].items():
                if logical_path not in logical_path_map:
                    logical_path_map[logical_path] = set()
                logical_path_map[logical_path].update(content_files)

    return logical_path_map

import os

def validate_fixity(self, fixity, manifest_files):
    """Validate fixity block in inventory.

    Check the structure of the fixity block and makes sure that only files
    listed in the manifest are referenced.
    """
    if not isinstance(fixity, dict):
        raise ValueError("Fixity block must be a dictionary")

    for file_path, fixity_info in fixity.items():
        if file_path not in manifest_files:
            raise ValueError(f"File '{file_path}' in fixity block is not listed in the manifest")

        if not isinstance(fixity_info, dict):
            raise ValueError(f"Fixity info for file '{file_path}' must be a dictionary")

        if 'algorithm' not in fixity_info or 'value' not in fixity_info:
            raise ValueError(f"Fixity info for file '{file_path}' must contain 'algorithm' and 'value' keys")

        if not isinstance(fixity_info['algorithm'], str) or not isinstance(fixity_info['value'], str):
            raise ValueError(f"Fixity 'algorithm' and 'value' for file '{file_path}' must be strings")

