def pretty(self, indent=0, debug=False):
    """
    Return a pretty formatted representation of self.
    """
    indent_str = ' ' * indent
    parts = []
    parts.append(f"{indent_str}<{self.__class__.__name__}>")
    for key, value in self.__dict__.items():
        if isinstance(value, (list, tuple, set)):
            parts.append(f"{indent_str}  {key}: [{', '.join(map(str, value))}]")
        elif isinstance(value, dict):
            parts.append(f"{indent_str}  {key}: {{")
            parts.extend(value.pretty(indent + 4, debug).split('\n'))
            parts.append(f"{indent_str}  }}")
        else:
            parts.append(f"{indent_str}  {key}: {value}")
    if debug:
        parts.append(f"{indent_str}  [DEBUG] {self.__dict__}")
    return '\n'.join(parts)

import sys

def tzname_in_python2(namefunc):
    """Change unicode output into bytestrings in Python 2

    tzname() API changed in Python 3. It used to return bytes, but was changed
    to unicode strings
    """
    def inner_func(*args, **kwargs):
        result = namefunc(*args, **kwargs)
        if sys.version_info[0] < 3:
            return result.encode()
        else:
            return result
    return inner_func

