import subprocess

def run_command(commands, args, cwd=None, verbose=False, hide_stderr=False, env=None):
    """Call the given command(s)."""
    try:
        if verbose:
            print(f"Running command: {commands} with args: {args}")

        if hide_stderr:
            stderr = subprocess.DEVNULL
        else:
            stderr = subprocess.STDOUT

        result = subprocess.check_output([commands] + args, cwd=cwd, stderr=stderr, env=env, shell=False)
        if verbose:
            print(f"Command output: {result.decode('utf-8')}")
        return result.decode('utf-8')
    except subprocess.CalledProcessError as e:
        if verbose:
            print(f"Command failed with output: {e.output.decode('utf-8')}")
        raise Exception(f"Command failed with return code {e.returncode}: {e.output.decode('utf-8')}")

