import os

def find_path_type(path):
    """Return a string indicating the type of thing at the given path.

    Return values:
        'root' - looks like an OCFL Storage Root
        'object' - looks like an OCFL Object
        'file' - a file, might be an inventory
        other string explains error description

    Looks only at "0=*" Namaste files to determine the directory type.
    """
    if not os.path.exists(path):
        return "Path does not exist"

    if os.path.isfile(path):
        return "file"

    if not os.path.isdir(path):
        return "Not a directory"

    namaste_files = [f for f in os.listdir(path) if f.startswith("0=")]
    if not namaste_files:
        return "No Namaste file found"

    if len(namaste_files) > 1:
        return "Multiple Namaste files found"

    namaste_file = os.path.join(path, namaste_files[0])
    if not os.path.isfile(namaste_file):
        return "Namaste file is not a valid file"

    with open(namaste_file, 'r') as f:
        content = f.read().strip()

    if content == "OCFL Storage Root":
        return "root"
    elif content == "OCFL Object":
        return "object"
    else:
        return "Unknown Namaste file content"

def amend_bzparams(self, params, bug_ids):
    """Amend the Bugzilla params"""
    if not isinstance(bug_ids, list):
        raise ValueError("bug_ids must be a list of Bugzilla bug IDs")

    if not isinstance(params, dict):
        raise ValueError("params must be a dictionary of parameters to amend")

    for bug_id in bug_ids:
        result = self.request(f'bug/{bug_id}', 'GET')
        if 'error' in result:
            raise Exception(f"Error retrieving bug {bug_id}: {result['message']}")

        bug_data = result['bugs'][0]
        updated_params = {**bug_data, **params}

        update_result = self.request(f'bug/{bug_id}', 'PUT', json=updated_params)
        if 'error' in update_result:
            raise Exception(f"Error updating bug {bug_id}: {update_result['message']}")

