from typing import List, Optional

def int_to_string(number: int, alphabet: List[str], padding: Optional[int] = None) -> str:
    """
    Convert a number to a string, using the given alphabet.

    The output has the most significant digit first.
    """
    if number < 0:
        raise ValueError("Number must be non-negative")

    base = len(alphabet)
    if base < 2:
        raise ValueError("Alphabet must contain at least two characters")

    if number == 0:
        return alphabet[0]

    digits = []
    while number:
        digits.append(alphabet[number % base])
        number //= base

    if padding is not None:
        digits.extend([alphabet[0]] * (padding - len(digits)))

    return ''.join(reversed(digits))

def replace_dots(value, arg):
    """Replaces all values of '.' to arg from the given string"""
    return value.replace('.', arg)

def subclasses(cls):
    """Return all subclasses of a class, recursively"""
    seen = set()
    queue = set([cls])

    while queue:
        c = queue.pop()
        seen.add(c)

        sc = c.__subclasses__()
        for c in sc:
            if c not in seen:
                queue.add(c)

    seen.remove(cls)
    return seen

