from logging import LogRecord

def load_configurations(config_filenames, overrides=None, resolve_env=True):
    '''
    Given a sequence of configuration filenames, load and validate each configuration file. Return
    the results as a tuple of: dict of configuration filename to corresponding parsed configuration,
    and sequence of logging.LogRecord instances containing any parse errors.
    '''
    configurations = {}
    errors = []

    for filename in config_filenames:
        if not os.path.exists(filename):
            error = LogRecord(name='config_loader', level=logging.ERROR, pathname=filename, lineno=0, msg=f"File not found: {filename}", args=(), exc_info=None)
            errors.append(error)
            continue

        try:
            if filename.endswith('.toml'):
                with open(filename) as fd:
                    config = toml.load(fd)
            elif filename.endswith('.yaml') or filename.endswith('.yml'):
                with open(filename) as fd:
                    config = yaml.safe_load(fd)
            else:
                error = LogRecord(name='config_loader', level=logging.ERROR, pathname=filename, lineno=0, msg=f"Unsupported file format: {filename}", args=(), exc_info=None)
                errors.append(error)
                continue

            if overrides:
                config.update(overrides)

            if resolve_env:
                for key, value in config.items():
                    if isinstance(value, str):
                        config[key] = os.path.expandvars(value)

            configurations[filename] = config

        except (toml.TomlDecodeError, yaml.YAMLError) as e:
            error = LogRecord(name='config_loader', level=logging.ERROR, pathname=filename, lineno=0, msg=f"Error parsing file: {filename}", args=(str(e),), exc_info=None)
            errors.append(error)

    return configurations, errors

