def verifyClass(iface, candidate, tentative=False):
    """
    Verify that the *candidate* might correctly provide *iface*.
    """
    if not isinstance(iface, type) or not isinstance(candidate, type):
        raise TypeError("Both iface and candidate must be types")

    if tentative:
        # Check if candidate is a subclass of iface
        return issubclass(candidate, iface)
    else:
        # Check if candidate is exactly iface
        return candidate is iface

def determine_metaclass(bases, explicit_mc=None):
    """Determine metaclass from 1+ bases and optional explicit __metaclass__"""
    if explicit_mc is not None:
        return explicit_mc

    metaclasses = set()
    for base in bases:
        if hasattr(base, '__metaclass__'):
            metaclasses.add(base.__metaclass__)
        elif hasattr(base, '__class__'):
            metaclasses.add(base.__class__)

    if metaclasses:
        return metaclasses.pop()

    return type

class Dictator:
    def __init__(self):
        self.data = {}

    def pop(self, key, default=__marker):
        """
        D.pop(k[,d]) -> v, remove specified key and return the corresponding value.
        If key is not found, d is returned if given, otherwise KeyError is raised.
        """
        if key in self.data:
            return self.data.pop(key)
        elif default is not __marker:
            return default
        else:
            raise KeyError(key)

__marker = object()

from collections import OrderedDict

class LFUCache(OrderedDict):
    def __init__(self, *args, **kwargs):
        super().__init__(*args, **kwargs)
        self._counter = {}

    def __setitem__(self, key, value):
        super().__setitem__(key, value)
        self._counter[key] = self._counter.get(key, 0) + 1
        self.move_to_end(key)

    def __getitem__(self, key):
        value = super().__getitem__(key)
        self._counter[key] += 1
        self.move_to_end(key)
        return value

    def popitem(self):
        """Remove and return the `(key, value)` pair least frequently used."""
        if not self:
            raise KeyError('popitem(): dictionary is empty')

        # Find the key with the minimum frequency
        min_freq = min(self._counter.values())
        for key, freq in self._counter.items():
            if freq == min_freq:
                del self._counter[key]
                return key, self.pop(key)

def popitem(self):
    """Remove and return the `(key, value)` pair most recently used."""
    if not self:
        raise KeyError("popitem(): dictionary is empty")
    key = next(reversed(self))
    value = self.pop(key)
    return (key, value)

import random

class RandomDict(dict):
    def popitem(self):
        """Remove and return a random `(key, value)` pair."""
        if not self:
            raise KeyError('popitem(): dictionary is empty')
        key = random.choice(list(self))
        return key, self.pop(key)

