import pytz

def _validate_fromutc_inputs(func):
    def wrapper(self, dt):
        if not isinstance(dt, datetime):
            raise TypeError("Input must be a datetime object")
        if dt.tzinfo is None:
            raise ValueError("Input datetime must be timezone-aware")
        return func(self, dt)
    return wrapper

class TimezoneConverter:
    def __init__(self, target_timezone):
        self.target_timezone = pytz.timezone(target_timezone)

    @_validate_fromutc_inputs
    def fromutc(self, dt):
        """
        Given a timezone-aware datetime in a given timezone, calculates a
        timezone-aware datetime in a new timezone.

        Since this is the one time that we *know* we have an unambiguous
        datetime object, we take this opportunity to determine whether the
        datetime is ambiguous and in a "fold" state (e.g. if it's the first
        occurrence, chronologically, of the ambiguous datetime).

        :param dt:
            A timezone-aware :class:`datetime.datetime` object.
        """
        # Convert the input datetime to the target timezone
        target_dt = dt.astimezone(self.target_timezone)

        # Determine if the datetime is ambiguous
        ambiguous = False
        try:
            # Check if there are two possible interpretations of the datetime
            target_dt.replace(fold=1)
            ambiguous = True
        except ValueError:
            pass

        # Return the converted datetime with fold information
        return target_dt.replace(fold=ambiguous)

