import requests
from urllib.parse import quote

def retrieve_and_parse_diaspora_webfinger(handle):
    """
    Retrieve a and parse a remote Diaspora webfinger document.

    :arg handle: Remote handle to retrieve
    :returns: dict
    """
    try:
        host = handle.split("@")[1]
    except AttributeError:
        print("retrieve_and_parse_diaspora_webfinger: invalid handle given: %s" % handle)
        return None

    def fetch_document(host, path):
        url = f"https://{host}{path}"
        response = requests.get(url)
        if response.status_code == 200:
            return response.text, response.status_code, None
        else:
            return None, response.status_code, response.text

    def parse_diaspora_webfinger(document):
        import json
        return json.loads(document)

    document, code, exception = fetch_document(
        host=host, path="/.well-known/webfinger?resource=acct:%s" % quote(handle),
    )
    if document:
        return parse_diaspora_webfinger(document)

    def retrieve_diaspora_host_meta(host):
        document, code, exception = fetch_document(host=host, path="/.well-known/host-meta")
        if exception:
            return None
        from lxml import etree
        root = etree.fromstring(document)
        return root

    hostmeta = retrieve_diaspora_host_meta(host)
    if not hostmeta:
        return None

    url = hostmeta.find("{http://www.w3.org/2007/05/addressing}Link[@rel='lrdd']").get("{http://www.w3.org/1999/xhtml}template").replace("{uri}", quote(handle))
    document, code, exception = fetch_document(url)
    if exception:
        return None

    return parse_diaspora_webfinger(document)

