import os
from pathlib import Path

class PluginManager:
    _plugin_classes = {}

    @classmethod
    def plugins_manager(cls):
        """Gets the plugin manager. """
        return cls

    @classmethod
    def register_plugin(cls, plugin_class):
        """Registers a plugin class.

        The plugin classes are identified based on their lower case name.

        Args:
          plugin_class (type): class of the plugin.

        Raises:
          KeyError: if plugin class is already set for the corresponding name.
        """
        plugin_name = plugin_class.NAME.lower()
        if plugin_name in cls._plugin_classes:
            raise KeyError(f'Plugin class already set for name: {plugin_class.NAME}')
        cls._plugin_classes[plugin_name] = plugin_class

    @classmethod
    def get_plugin(cls, name):
        """Return plugin class.

        @param name: the plugin label.
        """
        plugin_name = name.lower()
        if plugin_name in cls._plugin_classes:
            return cls._plugin_classes[plugin_name]
        raise RuntimeError(f'Plugin "{name}" not known.')

    @classmethod
    def discover_plugins(cls, directories):
        """Discover the plugin classes contained in Python files, given a
        list of directory names to scan. Return a list of plugin classes.
        """
        for directory in directories:
            for root, _, files in os.walk(directory):
                for file in files:
                    if file.endswith('_plugin.py'):
                        module_path = Path(root) / file
                        module_name = module_path.stem
                        module = importlib.import_module(f'.{module_name}', package=root)
                        for attr_name in dir(module):
                            attr = getattr(module, attr_name)
                            if isinstance(attr, type) and issubclass(attr, Plugin) and attr is not Plugin:
                                cls.register_plugin(attr)
        return list(cls._plugin_classes.values())

